function removeDuplicatesString(s) {
  const chars = s.split('');
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < chars.length - 1; i++) {
      if (chars[i] === chars[i + 1]) {
        chars.splice(i, 2);
        changed = true;
        break;
      }
    }
  }
  return chars.join('');
}

function removeDuplicatesString(s) {
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (stack.length > 0 && stack[stack.length - 1] === ch) {
      stack.pop();
    } else {
      stack.push(ch);
    }
  }
  return stack.join('');
}

def removeDuplicatesString(s: str) -> str:
    chars = list(s)
    changed = True
    while changed:
        changed = False
        for i in range(len(chars) - 1):
            if chars[i] == chars[i + 1]:
                del chars[i:i + 2]
                changed = True
                break
    return "".join(chars)

def removeDuplicatesString(s: str) -> str:
    stack = []
    for ch in s:
        if stack and stack[-1] == ch:
            stack.pop()
        else:
            stack.append(ch)
    return "".join(stack)
